import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const CreerStudent = () => {
  const [nom, setNom] = useState("");
  const [email, setEmail] = useState("");
  const [classe, setClasse] = useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem("token");
      const response = await fetch("http://localhost:3000/api/users", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          nom,
          email,
          classe,
          role: "student",
        }),
      });

      if (response.ok) {
        alert("Étudiant créé avec succès !");
        navigate("/etudiants");
      } else {
        alert("Erreur lors de la création de l'étudiant");
      }
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div style={{ padding: "2rem" }}>
      <h1>Créer un nouvel étudiant</h1>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1rem", maxWidth: "400px" }}>
        <input type="text" placeholder="Nom" value={nom} onChange={(e) => setNom(e.target.value)} required />
        <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
        <input type="text" placeholder="Classe" value={classe} onChange={(e) => setClasse(e.target.value)} />
        <button type="submit" style={{ padding: "0.6rem 1rem", borderRadius: "8px", background: "#16a34a", color: "white", border: "none", cursor: "pointer" }}>
          Créer Étudiant
        </button>
      </form>
    </div>
  );
};

export default CreerStudent;
